import os


def index_files(root, extensions=None):
    """Index files under ``root``.

    Returns a mapping of relative path to size in bytes, filtered by
    ``extensions`` when provided.
    """
    if not os.path.isdir(root):
        raise FileNotFoundError(root)
    if extensions is None:
        normalized = None
    else:
        normalized = set()
        for ext in extensions:
            ext = str(ext)
            if not ext.startswith("."):
                ext = "." + ext
            normalized.add(ext.lower())
    result = {}
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            if normalized is not None:
                _, suffix = os.path.splitext(name)
                if suffix.lower() not in normalized:
                    continue
            full_path = os.path.join(dirpath, name)
            rel_path = os.path.relpath(full_path, root)
            result[rel_path] = os.path.getsize(full_path)
    return result

